preConditionHook:
// EL: Value1 = Average((H+L)/2, v1), Value2 = Average((H+L)/2, v1+v3) -- both
// plain Average over a PRICE expression, which has real history, so they are
// recomputed fresh from the bars every time (EL_Summation_Probe: Average is
// not a rolling sum). Summation adds Price[0], Price[1], ... in that order and
// Average divides once afterwards; (H+L)/2 is evaluated per bar as written.
aoFast = 0.0;
for (int i = 0; i < (int)v1; ++i) {
    aoFast += (high[i] + low[i]) / 2.0;
}
aoFast = aoFast / (int)v1;
aoSlow = 0.0;
for (int i = 0; i < (int)(v1 + v3); ++i) {
    aoSlow += (high[i] + low[i]) / 2.0;
}
aoSlow = aoSlow / (int)(v1 + v3);
ao = aoFast - aoSlow;
// EL: AO is a VARIABLE, so AO[n] reads the variable's own history, which
// holds its initial 0 for every bar before the strategy's first evaluated
// one. Mirrored as a zero-seeded ring buffer holding lags 0..maxLag,
// re-seeded if the depth ever changes (see AtrRising).
{
    const int maxLag = (int)aback > (int)bback ? (int)aback : (int)bback;
    if (aoHistory.size() != (std::size_t)(maxLag + 1)) {
        aoHistory.assign((std::size_t)(maxLag + 1), 0.0);
        aoCursor = 0;
    }
}
aoHistory[aoCursor] = ao;
aoCursor = (aoCursor + 1) % aoHistory.size();
aoNear = aoHistory[(aoCursor + aoHistory.size() - 1 - (std::size_t)(int)aback) % aoHistory.size()];
aoFar = aoHistory[(aoCursor + aoHistory.size() - 1 - (std::size_t)(int)bback) % aoHistory.size()];
